export function TechIcon({
  icon,
  size = 20,
  color,
  className = "",
}: {
  icon: TechName;
  size?: number;
  color?: string
  className?: string
}) {
  const special = SPECIAL[icon];
  if (special) {
    return <>{special({ size, className })}</>
  }
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill={color ?? "currentColor"}
      aria-hidden="true"
      className={className}
    >
      <path d={PATHS[icon]} />
    </svg>
  );
}
